100	 * Parse the size out of a Proxmox disk config string, e.g.
101	 * "vmdata:vm-101-disk-0,size=50G" / ",size=32768M" / ",size=1T".
102	 * Returns GB (floor), or null when the string carries no size.
103	 */
104	export function parseDiskSizeGB(spec: string | undefined | null): number | null {
105	  if (typeof spec !== "string") return null;
106	  const m = /(?:^|,)size=(\d+(?:\.\d+)?)([KMGT]?)/i.exec(spec);
107	  if (!m) return null;
108	  const n = Number(m[1]);
109	  if (!Number.isFinite(n)) return null;
110	  switch ((m[2] || "").toUpperCase()) {
111	    case "T": return Math.floor(n * 1024);
112	    case "G": return Math.floor(n);
113	    case "M": return Math.floor(n / 1024);
114	    case "K": return Math.floor(n / 1024 / 1024);
115	    default:  return Math.floor(n / 1024 ** 3); // bare bytes
116	  }
117	}
