189	/**
190	 * Grow the guest filesystem online. Returns null on success, or a human-readable
191	 * reason plus the exact remediation commands when it could not be done.
192	 */
193	async function growGuestFilesystem(
194	  server: any,
195	  onStep: (pct: number, step: string) => Promise<void>,
196	): Promise<{ reason: string; commands: string } | null> {
197	  let layout: GuestLayout | null = null;
198	  try {
199	    return await withServerSsh(server, async (conn) => {
200	      await onStep(62, "Detecting the root filesystem");
201	      const detected = await detectLayout(conn);
202	      if ("error" in detected) {
203	        return { reason: detected.error, commands: manualCommands(null) };
204	      }
205	      layout = detected;
206	      const parentPath = `/dev/${layout.parentName}`;
207	      if (!DEV_PATH_RE.test(parentPath)) {
208	        return { reason: "could not identify the parent disk", commands: manualCommands(null) };
209	      }
210	
211	      // growpart ships in cloud-guest-utils (Debian/Ubuntu) or cloud-utils-growpart
212	      // (RHEL family). Fixed string — no interpolation.
213	      await onStep(70, "Preparing the guest tools");
214	      const ensure = await exec(
215	        conn,
216	        "if ! command -v growpart >/dev/null 2>&1; then " +
217	          "(DEBIAN_FRONTEND=noninteractive apt-get update -qq && DEBIAN_FRONTEND=noninteractive apt-get install -y cloud-guest-utils) || " +
218	          "dnf install -y cloud-utils-growpart || yum install -y cloud-utils-growpart || true; fi; " +
219	          "command -v growpart >/dev/null 2>&1 && echo OK || echo MISSING",
220	        SETUP_TIMEOUT_MS * 5,
221	      );
222	      if (!/\bOK\b/.test(ensure.stdout)) {
223	        return {
224	          reason: "growpart could not be installed on the server",
225	          commands: `apt-get install -y cloud-guest-utils || dnf install -y cloud-utils-growpart; ${manualCommands(layout)}`,
226	        };
227	      }
228	
229	      // Make the kernel notice the larger block device before growing anything.
230	      // Every interpolated value passed the allowlist above and is quoted anyway.
231	      await onStep(78, "Rescanning the virtual disk");
232	      await exec(
233	        conn,
234	        `echo 1 > /sys/class/block/${shellQuote(layout.parentName)}/device/rescan 2>/dev/null; ` +
235	          `partprobe ${shellQuote(parentPath)} >/dev/null 2>&1; ` +
236	          `udevadm settle >/dev/null 2>&1; true`,
237	        QUICK_TIMEOUT_MS,
238	      );
239	
240	      // growpart exits 1 with "NOCHANGE" when the partition is already maximal —
241	      // that is the idempotent-retry case, not a failure.
242	      await onStep(85, "Growing the root partition");
243	      const grow = await exec(
244	        conn,
245	        `growpart ${shellQuote(parentPath)} ${shellQuote(layout.partNum)} 2>&1`,
246	        SETUP_TIMEOUT_MS,
247	      );
248	      const growOut = `${grow.stdout}${grow.stderr}`;
249	      if (grow.code !== 0 && !/NOCHANGE/i.test(growOut)) {
250	        return {
251	          reason: `growpart failed: ${growOut.trim().slice(0, 200)}`,
252	          commands: manualCommands(layout),
253	        };
254	      }
255	
256	      await onStep(92, "Growing the filesystem");
257	      const fsCmd =
258	        layout.fsType === "xfs"
259	          ? "xfs_growfs / 2>&1"
260	          : layout.fsType === "btrfs"
261	            ? "btrfs filesystem resize max / 2>&1"
262	            : `resize2fs ${shellQuote(layout.rootDevice)} 2>&1`;
263	      const fs = await exec(conn, fsCmd, SETUP_TIMEOUT_MS * 3);
264	      const fsOut = `${fs.stdout}${fs.stderr}`;
265	      // "Nothing to do" / "already N blocks long" are the no-op retry cases.
266	      if (fs.code !== 0 && !/nothing to do|already .* long|no change/i.test(fsOut)) {
267	        return {
268	          reason: `${layout.fsType} grow failed: ${fsOut.trim().slice(0, 200)}`,
269	          commands: manualCommands(layout),
270	        };
271	      }
272	      return null;
273	    });
274	  } catch (e: any) {
275	    // Unreachable / no credentials / timeout — the disk is still bigger.
276	    return {
277	      reason: String(e?.message ?? e).slice(0, 200),
278	      commands: manualCommands(layout),
279	    };
280	  }
281	}
