1000	async function reapStuckJobs() {
1001	  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
1002	  for (const job of stuck) {
1003	    const retriable = job.attempts < MAX_ATTEMPTS;
1004	    await db.job.update({
1005	      where: { id: job.id },
1006	      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
1007	    });
1008	    if (!retriable) {
1009	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
1010	      if (job.serverId) {
1011	        const s = await db.server.findUnique({ where: { id: job.serverId } });
1012	        if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
1013	          await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
1014	        }
1015	      }
1016	    }
1017	    console.log(`[worker] reaped stuck job ${job.id} (${job.type}) -> ${retriable ? "QUEUED" : "FAILED"}`);
1018	  }
