445	export async function serverAction(serverId: string, action: string) {
446	  const { user, server } = await ownedServer(serverId);
447	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
448	    start: "START",
449	    stop: "STOP",
450	    reboot: "REBOOT",
451	    reinstall: "REINSTALL",
452	    delete: "DELETE",
453	  };
454	  const type = allowed[action];
455	  if (!type) throw new Error("Invalid action");
456	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
457	    throw new Error("Server is suspended");
458	  }
459	
460	  // A reinstall wipes the whole VM, including any attached block-storage volume
461	  // (Proxmox purges every disk the VM owns). Refuse up front when a real volume
462	  // is attached so the customer detaches it first — this also avoids enqueuing a
463	  // job that the worker's matching guard would block (defense in depth).
464	  if (type === "REINSTALL") {
465	    const attachedVolumes = await db.volume.count({ where: { serverId, status: "ATTACHED" } });
466	    if (attachedVolumes > 0) {
467	      throw new Error(
468	        "Detach your data volume(s) before reinstalling — a reinstall wipes the server. Open Volumes to detach first, then reinstall.",
469	      );
470	    }
471	  }
472	
473	  const pending = await db.job.count({
474	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
475	  });
476	  if (pending > 0) return; // debounce: one job at a time per server
477	
478	  if (type === "DELETE") {
479	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
480	  }
481	  await db.job.create({ data: { type, serverId } });
482	  await audit(user.id, `server.${action}`, serverId);
483	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
484	  revalidatePath(`/dashboard/servers/${serverId}`);
485	}
