407	/**
408	 * Retention: keep only the newest `keep` backups for a VM on the backup storage,
409	 * deleting the older ones (best-effort per file, oldest first). Runs after every
410	 * successful backup so customer servers never accumulate beyond their limit.
411	 * Returns how many were deleted.
412	 */
413	export async function pruneBackups(client: any, vmid: number, keep: number): Promise<number> {
414	  const content: any[] = await client.get(`/nodes/${client.node}/storage/backup/content`, { content: "backup" });
415	  const mine = content
416	    .filter((b) => b.vmid === vmid && typeof b.volid === "string")
417	    .sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
418	  const toDelete = mine.slice(Math.max(0, keep));
419	  let deleted = 0;
420	  for (const b of toDelete) {
421	    try {
422	      await deleteBackup(client, b.volid);
423	      deleted++;
424	    } catch (e) {
425	      console.error(`[proxmox] pruneBackups: failed to delete ${b.volid}`, e);
426	    }
427	  }
428	  return deleted;
429	}
